edit('module-stage-guardian.lua',lambda s:s.replace("{'tcp','game'}","{'tcp','game','tcp2'}").replace("'eligible_tcp','eligible_game'","'eligible_tcp','eligible_game','eligible_tcp2'").replace("'allowed_tcp','allowed_game'","'allowed_tcp','allowed_game','allowed_tcp2'").replace("'tcp_state','game_state'","'tcp_state','game_state','tcp2_state'").replace("'tcp_pinned_state','game_pinned_state'","'tcp_pinned_state','game_pinned_state','tcp2_pinned_state'").replace("'tcp_permit','game_permit'","'tcp_permit','game_permit','tcp2_permit'").replace("'expiry_tcp','expiry_game'","'expiry_tcp','expiry_game','expiry_tcp2'"))
def epoch(s):
 s=s.replace("['tcp','udp']",slots).replace("[['tcp','tcp'],['udp','game']]","[['tcp','tcp'],['udp','game'],['tcp2','tcp2']]").replace("p.name==='B'?2:0","p.name==='B'?3:0")
 s=s.replace('const prerequisites=[];','const prerequisites=[];')
 s=s.replace("const f=selected[slot];const e=encode(\"/usr/bin/lua - \"+f.wan", "const f=selected[slot];if(prerequisites.some(q=>q.wan===f.wan))continue;const e=encode(\"/usr/bin/lua - \"+f.wan")
 s=s.replace("assert.equal(classified.decisions[1].class,'RT');","assert.equal(classified.decisions[1].class,'RT');assert.equal(classified.decisions[2].class,'BULK');")
 s=s.replace("&&fresh.tcp.some(f=>JSON.stringify(convert(f))===JSON.stringify(selected.tcp))","&&fresh.tcp.some(f=>JSON.stringify(convert(f))===JSON.stringify(selected.tcp))&&fresh.tcp.some(f=>JSON.stringify(convert(f))===JSON.stringify(selected.tcp2))")
 s=s.replace('twoWans:[selected.tcp.wan,selected.udp.wan]','naturalWanSet:[...new Set(Object.values(selected).map(f=>f.wan))],twoTcpBulkOneUdpRt:true')
 return s
edit('epoch-driver.mjs',epoch)
